class Solution {
public:
    int orderOfLargestPlusSign(int n, vector<vector<int>>& mines) {
        vector<vector<int>> grid(n, vector<int>(n, n));
        for (const auto& m : mines) {
            grid[m[0]][m[1]] = 0;
        }
        for (int r = 0; r < n; r++) {
            int count = 0;
            for (int c = 0; c < n; c++) {
                count = (grid[r][c] == 0) ? 0 : count + 1;
                grid[r][c] = min(grid[r][c], count);
            }
            count = 0;
            for (int c = n - 1; c >= 0; c--) {
                count = (grid[r][c] == 0) ? 0 : count + 1;
                grid[r][c] = min(grid[r][c], count);
            }
        }
        int ans = 0;
        for (int c = 0; c < n; c++) {
            int count = 0;
            for (int r = 0; r < n; r++) {
                count = (grid[r][c] == 0) ? 0 : count + 1;
                grid[r][c] = min(grid[r][c], count);
            }
            count = 0;
            for (int r = n - 1; r >= 0; r--) {
                count = (grid[r][c] == 0) ? 0 : count + 1;
                grid[r][c] = min(grid[r][c], count);
                ans = max(ans, grid[r][c]);
            }
        }
        return ans;
    }
};

